  "Need by": "అవసరమైన తేదీ",
  "Nothing more to pay until you accept your personal offer. Leave any time before close for a full refund.": "మీ వ్యక్తిగత ఆఫర్ అంగీకరించే వరకు ఇంకేమీ చెల్లించనక్కర్లేదు. మూసే ముందు ఎప్పుడైనా వదిలేస్తే పూర్తి రీఫండ్.",
  "Invite neighbours": "పొరుగువారిని ఆహ్వానించండి",
  "Leave pool": "పూల్ వదిలేయండి",
  "Sellers have bid. POOL is setting your price.": "విక్రేతలు బిడ్ వేశారు. POOL మీ ధర నిర్ణయిస్తోంది.",
  "{n} sealed bids were opened at close and ranked by the published rule. Your personal offer arrives by {time}. If prices aren’t ready by then, your booking is refunded in full.": "మూసినప్పుడు {n} సీల్డ్ బిడ్‌లు తెరిచి, ప్రచురించిన నియమం ప్రకారం ర్యాంక్ చేశాం. మీ వ్యక్తిగత ఆఫర్ {time} లోపు వస్తుంది. అప్పటికి ధరలు సిద్ధం కాకపోతే, మీ బుకింగ్ పూర్తిగా రీఫండ్.",
  "Your personal offer is ready": "మీ వ్యక్తిగత ఆఫర్ సిద్ధం",
