  "Your offer expired": "మీ ఆఫర్ గడువు ముగిసింది",
  "Your booking of {amt} was refunded in full.": "మీ {amt} బుకింగ్ పూర్తిగా రీఫండ్ అయింది.",
  "How this pool works": "ఈ పూల్ ఎలా పనిచేస్తుంది",
  "What every seller must offer": "ప్రతి విక్రేత ఇవ్వాల్సినవి",
