  "Installation by a brand-authorised team": "బ్రాండ్ అనుమతి ఉన్న టీమ్ ఇన్‌స్టలేషన్",
  "area-wise slots, 4-digit code": "ప్రాంతాల వారీ స్లాట్లు, 4-అంకెల కోడ్",
