  "Ratings are tied to completed orders, so they can’t be bought or faked.": "रेटिंग सिर्फ़ पूरे हुए ऑर्डर से जुड़ी हैं, इसलिए न ख़रीदी जा सकती हैं न नकली बनाई जा सकती हैं।",
