  "Add at least one photo. It settles most cases in hours, not days.": "कम से कम एक फ़ोटो जोड़ें। ज़्यादातर मामले दिनों में नहीं, घंटों में सुलझते हैं।",
  "Issue reported. {s} must reply within 24 hours.": "शिकायत दर्ज हुई। {s} को 24 घंटे में जवाब देना है।",
  "The seller must reply within 24 hours. If they don’t, or you disagree, POOL decides within 48 hours. If you’re owed money, POOL refunds you first and recovers it from the seller.": "विक्रेता को 24 घंटे में जवाब देना है। अगर वे जवाब न दें या आप असहमत हों, तो POOL 48 घंटे में फ़ैसला करेगा। अगर आपका पैसा बनता है, तो POOL पहले आपको लौटाएगा और बाद में विक्रेता से वसूलेगा।",
  "You haven’t given your code, so your money is still held. The seller isn’t paid while this is open.": "आपने कोड नहीं दिया है, इसलिए आपका पैसा अभी रोका हुआ है। जब तक यह खुला है, विक्रेता को पैसा नहीं मिलेगा।",
