  "Your POOL offer will be shown next to this. If outside is cheaper for you, we’ll say so.": "आपका POOL ऑफ़र इसके बगल में दिखेगा। अगर बाहर आपके लिए सस्ता हुआ, तो हम बताएँगे।",
