  "More real buyers make the pool more attractive to sellers, and every completed purchase grows the Wave Drop for everyone. No referral cash, no spam.": "ज़्यादा असली ख़रीदार हों तो पूल विक्रेताओं के लिए आकर्षक बनता है, और हर पूरी ख़रीद सबका वेव ड्रॉप बढ़ाती है। कोई रेफ़रल कैश नहीं, कोई स्पैम नहीं।",
