  "You get your {amt} booking back in full, to the same UPI or card. You can rejoin while the pool is open.": "आपकी {amt} की बुकिंग उसी UPI या कार्ड में पूरी लौटेगी। पूल खुला रहने तक दोबारा जुड़ सकते हैं।",
