  "{n} accepted orders would fill a {pot} pot. Only completed purchases count; paid when the wave closes.": "{n} स्वीकार हुए ऑर्डर {pot} का पॉट भरेंगे। सिर्फ़ पूरी ख़रीदें गिनी जाती हैं; वेव बंद होने पर मिलता है।",
  "From order {k}, each adds {amt}.": "ऑर्डर {k} से, हर एक {amt} जोड़ता है।",
  "What if I don’t like the price?": "दाम पसंद न आए तो?",
  "Walk away. Your booking comes back in full. Accept and Walk away are equal choices, and no reply also means a full refund.": "मना कर दें। आपकी बुकिंग पूरी लौटेगी। स्वीकार और मना बराबर विकल्प हैं, और जवाब न देने पर भी पूरा रिफ़ंड।",
  "When do I pay the rest?": "बाकी कब चुकाऊँ?",
  "Only after you accept your personal offer: pay in full, by card EMI, or at your door by UPI or card after checking the box. Never cash.": "निजी ऑफ़र स्वीकार करने के बाद ही: पूरा, कार्ड EMI से, या डिब्बा जाँचकर दरवाज़े पर UPI या कार्ड से। नकद नहीं।",
  "Who holds my money?": "मेरा पैसा किसके पास रहता है?",
  "A licensed payment company. It releases the seller’s share only after you give your handover code.": "एक लाइसेंसशुदा पेमेंट कंपनी के पास। आपका हैंडओवर कोड देने के बाद ही वह विक्रेता का हिस्सा छोड़ती है।",
  "What if no seller bids, or none meets the rules?": "अगर कोई विक्रेता बोली न लगाए, या कोई नियम पूरे न करे?",
  "Then it’s “no deal” and every booking is refunded automatically.": "तब “सौदा नहीं हुआ”, और हर बुकिंग अपने-आप लौटा दी जाती है।",
  "Can the closing time change?": "क्या बंद होने का समय बदल सकता है?",
  "Only later, and only if every buyer in the pool agrees. Never earlier. Every change is logged.": "सिर्फ़ आगे, और तभी जब पूल का हर ख़रीदार माने। कभी पहले नहीं। हर बदलाव दर्ज होता है।",
  "Who sees my name and number?": "मेरा नाम और नंबर कौन देखता है?",
  "Nobody until you accept an offer. Then only the winning seller, for delivery.": "ऑफ़र स्वीकार करने तक कोई नहीं। फिर सिर्फ़ जीतने वाला विक्रेता, डिलीवरी के लिए।",
  "What is the Wave Drop?": "वेव ड्रॉप क्या है?",
  "Each completed purchase drops a small amount, set by the seller, into a shared pot. When the wave closes, the pot is split equally among buyers who completed. Real numbers only.": "हर पूरी ख़रीद, विक्रेता की तय की हुई एक छोटी रक़म साझा पॉट में डालती है। वेव बंद होने पर पॉट ख़रीद पूरी करने वालों में बराबर बँटता है। सिर्फ़ असली आँकड़े।",
  "Questions buyers ask": "ख़रीदारों के सवाल",
  "This pool has closed": "यह पूल बंद हो चुका है",
  "Start a new pool for this product, or watch it to hear when the next one opens.": "इस प्रोडक्ट के लिए नया पूल शुरू करें, या अगला खुलने पर ख़बर पाने के लिए नज़र रखें।",
