  "You're in. {n} households have now paid a booking. We'll message you when the pool closes and your offer is ready.": "आप जुड़ गए। अब तक {n} परिवारों ने बुकिंग चुकाई है। पूल बंद होने और ऑफ़र तैयार होने पर हम मैसेज करेंगे।",
