  "You’re starting a pool. Neighbours who want the same product can join, verified sellers in your area are invited to bid privately, and the closing time you choose is the one everyone sees.": "आप एक पूल शुरू कर रहे हैं। वही प्रोडक्ट चाहने वाले पड़ोसी जुड़ सकते हैं, आपके इलाक़े के सत्यापित विक्रेताओं को गुप्त बोली के लिए बुलाया जाता है, और आपका चुना बंद होने का समय सबको दिखता है।",
  "Who can join": "कौन जुड़ सकता है",
