  "Brand teams install in the same week. Interiors not ready? Postpone up to 45 days, and the seller’s installation hold waits too.": "ब्रांड टीमें उसी हफ़्ते लगाती हैं। इंटीरियर तैयार नहीं? 45 दिन तक टालें, विक्रेता का इंस्टॉलेशन होल्ड भी इंतज़ार करेगा।",
  "Builder name, building and needs are sample data for the demo.": "बिल्डर का नाम, बिल्डिंग और ज़रूरतें डेमो के लिए नमूना डेटा हैं।",
