  "{host} links often point to a post, not a product. Search by name instead, or send it to a POOL expert.": "{host} के लिंक अक्सर प्रोडक्ट की जगह किसी पोस्ट के होते हैं। नाम से खोजें, या POOL विशेषज्ञ को भेजें।",
  "Search instead": "इसकी जगह खोजें",
