  "A person on the POOL team will find the exact model and reply in the app and on WhatsApp within 24 hours. Nothing is charged.": "POOL टीम का कोई व्यक्ति सही मॉडल ढूँढकर 24 घंटे में ऐप और WhatsApp पर जवाब देगा। कुछ नहीं लिया जाएगा।",
